const controlsBeforeLongWalking=renderControls;renderControls=function(){controlsBeforeLongWalking();const o=object();if(!isAnimatedCharacter(o))return;const panel=document.createElement('details');panel.id='longWalkTools';panel.innerHTML='<summary>Walk for longer</summary><label>Walk for (seconds)<input id="longWalkSeconds" type="number" min="0.1" step="1" value="10"></label><label><input id="longWalkInPlace" type="checkbox" checked> Walk in place</label><label>Facing<select id="longWalkFacing"><option value="1">Right</option><option value="-1">Left</option></select></label><button id="createLongWalk">Add walking</button><p class="note">Long walks continue into new scenes with the same environment and step rhythm. Turn off Walk in place to use the selected walk’s destination. A project can contain up to 99 scenes.</p>';($('controls').querySelector('[data-character-panel="animate"]')||$('controls')).append(panel);panel.querySelectorAll('input,select,button').forEach(e=>e.disabled=!!o.locked);$('createLongWalk').onclick=()=>{try{walkForDuration(o,+$('longWalkSeconds').value,{inPlace:$('longWalkInPlace').checked,direction:+$('longWalkFacing').value})}catch(e){toast(e.message)}}};
